            "comentario": "Segundo o Acordo Ortográfico, quando o prefixo termina com consoante e a palavra seguinte começa com a mesma letra ('r' ou 's'), emprega-se hífen e duplica-se a consoante em palavras aglutinadas, ou aplica-se a regra do hfen com 'r' (sub-reino)."
