            "enunciado": "Em uma repartição pública da Câmara Municipal, 4 analistas conseguem arquivar um lote de processos em exatamente 6 horas de trabalho contínuo. Mantendo-se a mesma proporção e o ritmo de trabalho, quanto tempo levariam 3 analistas para realizar essa mesma tarefa?",
